"use client";
/* Hatch, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Hatch(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("hatch"); }, []);
  return React.createElement("piix-pal", { "pal": "hatch", ...piixAttrs(props) });
}

export default Hatch;
